375	fn encode_restart_arguments(arguments: &[OsString]) -> OsString {
376	    // `Start-Process` accepts a single native command line, so quote each argument according to
377	    // the Windows argv parsing rules before passing the complete string through the environment.
378	    let mut encoded = Vec::new();
379	
380	    for (index, argument) in arguments.iter().enumerate() {
381	        if index > 0 {
382	            encoded.push(b' ' as u16);
383	        }
384	        encoded.push(b'"' as u16);
385	
386	        let mut backslash_count = 0;
387	        for code_unit in argument.encode_wide() {
388	            if code_unit == b'\\' as u16 {
389	                backslash_count += 1;
390	            } else {
391	                if code_unit == b'"' as u16 {
392	                    encoded.extend(std::iter::repeat_n(b'\\' as u16, backslash_count * 2 + 1));
393	                } else {
394	                    encoded.extend(std::iter::repeat_n(b'\\' as u16, backslash_count));
395	                }
396	                backslash_count = 0;
397	                encoded.push(code_unit);
398	            }
399	        }
400	
401	        encoded.extend(std::iter::repeat_n(b'\\' as u16, backslash_count * 2));
402	        encoded.push(b'"' as u16);
403	    }
404	
405	    OsString::from_wide(&encoded)
406	}
