473	    fn restart(&self, binary_path: Option<PathBuf>, arguments: Vec<OsString>) {
474	        let pid = std::process::id();
475	        let Some(app_path) = binary_path.or(self.app_path().log_err()) else {
476	            return;
477	        };
478	        let script = r#"
479	            $pidToWaitFor = $env:ZED_RESTART_PID
480	            $exePath = $env:ZED_RESTART_EXECUTABLE
481	            $argumentList = $env:ZED_RESTART_ARGUMENTS
482	
483	            [Environment]::SetEnvironmentVariable("ZED_RESTART_PID", $null)
484	            [Environment]::SetEnvironmentVariable("ZED_RESTART_EXECUTABLE", $null)
485	            [Environment]::SetEnvironmentVariable("ZED_RESTART_ARGUMENTS", $null)
486	
487	            while ($true) {
488	                $process = Get-Process -Id $pidToWaitFor -ErrorAction SilentlyContinue
489	                if (-not $process) {
490	                    if ([string]::IsNullOrEmpty($argumentList)) {
491	                        Start-Process -FilePath $exePath
492	                    } else {
493	                        Start-Process -FilePath $exePath -ArgumentList $argumentList
494	                    }
495	                    break
496	                }
497	                Start-Sleep -Seconds 0.1
498	            }
499	            "#;
500	
501	        // Defer spawning to the foreground executor so it runs after the
502	        // current `AppCell` borrow is released. On Windows, `Command::spawn()`
503	        // can pump the Win32 message loop (via `CreateProcessW`), which
504	        // re-enters message handling possibly resulting in another mutable
505	        // borrow of the `AppCell` ending up with a double borrow panic
506	        self.foreground_executor
507	            .spawn(async move {
508	                let mut command = new_std_command(get_windows_system_shell());
509	                let arguments = encode_restart_arguments(&arguments);
510	                command
511	                    .arg("-command")
512	                    .arg(script)
513	                    .env("ZED_RESTART_PID", pid.to_string())
514	                    .env("ZED_RESTART_EXECUTABLE", app_path)
515	                    .env("ZED_RESTART_ARGUMENTS", arguments);
