832	    fn write_credentials(&self, url: &str, username: &str, password: &[u8]) -> Task<Result<()>> {
833	        // CredWriteW rejects larger blobs with the opaque RPC error
834	        // 0x800706F7 "The stub received bad data", so fail with a clear
835	        // message instead.
836	        if password.len() > CRED_MAX_CREDENTIAL_BLOB_SIZE as usize {
837	            return Task::ready(Err(anyhow!(
838	                "credential for {url} is {} bytes, which exceeds the Windows Credential Manager limit of {CRED_MAX_CREDENTIAL_BLOB_SIZE} bytes",
839	                password.len()
840	            )));
841	        }
842	        let password = password.to_vec();
843	        let mut username = username.encode_utf16().chain(Some(0)).collect_vec();
844	        let mut target_name = windows_credentials_target_name(url)
845	            .encode_utf16()
846	            .chain(Some(0))
847	            .collect_vec();
848	        self.foreground_executor().spawn(async move {
849	            let credentials = CREDENTIALW {
850	                LastWritten: unsafe { GetSystemTimeAsFileTime() },
851	                Flags: CRED_FLAGS(0),
852	                Type: CRED_TYPE_GENERIC,
853	                TargetName: PWSTR::from_raw(target_name.as_mut_ptr()),
854	                CredentialBlobSize: password.len() as u32,
855	                CredentialBlob: password.as_ptr() as *mut _,
856	                Persist: CRED_PERSIST_LOCAL_MACHINE,
857	                UserName: PWSTR::from_raw(username.as_mut_ptr()),
858	                ..CREDENTIALW::default()
859	            };
860	            unsafe {
861	                CredWriteW(&credentials, 0).map_err(|err| {
862	                    anyhow!(
863	                        "Failed to write credentials to Windows Credential Manager: {}",
864	                        err,
865	                    )
866	                })?;
867	            }
868	            Ok(())
869	        })
870	    }
871	
872	    fn read_credentials(&self, url: &str) -> Task<Result<Option<(String, Vec<u8>)>>> {
873	        let target_name = windows_credentials_target_name(url)
874	            .encode_utf16()
875	            .chain(Some(0))
876	            .collect_vec();
877	        self.foreground_executor().spawn(async move {
878	            let mut credentials: *mut CREDENTIALW = std::ptr::null_mut();
879	            let result = unsafe {
880	                CredReadW(
881	                    PCWSTR::from_raw(target_name.as_ptr()),
882	                    CRED_TYPE_GENERIC,
883	                    None,
884	                    &mut credentials,
885	                )
886	            };
887	
888	            if let Err(err) = result {
889	                // ERROR_NOT_FOUND means the credential doesn't exist.
890	                // Return Ok(None) to match macOS and Linux behavior.
891	                if err.code() == ERROR_NOT_FOUND.to_hresult() {
892	                    return Ok(None);
893	                }
894	                return Err(err.into());
895	            }
896	
897	            if credentials.is_null() {
898	                Ok(None)
899	            } else {
900	                let username: String = unsafe { (*credentials).UserName.to_string()? };
901	                let credential_blob = unsafe {
902	                    std::slice::from_raw_parts(
903	                        (*credentials).CredentialBlob,
904	                        (*credentials).CredentialBlobSize as usize,
905	                    )
906	                };
907	                let password = credential_blob.to_vec();
908	                unsafe { CredFree(credentials as *const _ as _) };
909	                Ok(Some((username, password)))
910	            }
911	        })
912	    }
