988	    fn handle_msg(
989	        self: &Rc<Self>,
990	        handle: HWND,
991	        msg: u32,
992	        wparam: WPARAM,
993	        lparam: LPARAM,
994	    ) -> LRESULT {
995	        let handled = match msg {
996	            WM_GPUI_CLOSE_ONE_WINDOW
997	            | WM_GPUI_TASK_DISPATCHED_ON_MAIN_THREAD
998	            | WM_GPUI_DOCK_MENU_ACTION
999	            | WM_GPUI_KEYBOARD_LAYOUT_CHANGED
1000	            | WM_GPUI_GPU_DEVICE_LOST => self.handle_gpui_events(msg, wparam, lparam),
1001	            WM_POWERBROADCAST => self.handle_power_broadcast(wparam),
1002	            _ => None,
1003	        };
1004	        if let Some(result) = handled {
1005	            LRESULT(result)
1006	        } else {
1007	            unsafe { DefWindowProcW(handle, msg, wparam, lparam) }
1008	        }
1009	    }
1010	
1011	    fn handle_gpui_events(&self, message: u32, wparam: WPARAM, lparam: LPARAM) -> Option<isize> {
1012	        if wparam.0 != self.validation_number {
1013	            log::error!("Wrong validation number while processing message: {message}");
1014	            return None;
1015	        }
1016	        match message {
1017	            WM_GPUI_CLOSE_ONE_WINDOW => {
1018	                self.close_one_window(HWND(lparam.0 as _));
1019	                Some(0)
1020	            }
1021	            WM_GPUI_TASK_DISPATCHED_ON_MAIN_THREAD => self.run_foreground_task(),
1022	            WM_GPUI_DOCK_MENU_ACTION => self.handle_dock_action_event(lparam.0 as _),
1023	            WM_GPUI_KEYBOARD_LAYOUT_CHANGED => self.handle_keyboard_layout_change(),
1024	            WM_GPUI_GPU_DEVICE_LOST => self.handle_device_lost(lparam),
1025	            _ => unreachable!(),
1026	        }
1027	    }
1028	
1029	    fn close_one_window(&self, target_window: HWND) -> bool {
1030	        let Some(all_windows) = self.raw_window_handles.upgrade() else {
1031	            log::error!("Failed to upgrade raw window handles");
1032	            return false;
1033	        };
1034	        let mut lock = all_windows.write();
1035	        let index = lock
1036	            .iter()
1037	            .position(|handle| handle.as_raw() == target_window)
1038	            .unwrap();
1039	        lock.remove(index);
1040	
1041	        lock.is_empty()
1042	    }
