1111	    fn handle_dock_action_event(&self, action_idx: usize) -> Option<isize> {
1112	        let Some(action) = self
1113	            .state
1114	            .jump_list
1115	            .borrow()
1116	            .dock_menus
1117	            .get(action_idx)
1118	            .map(|dock_menu| dock_menu.action.boxed_clone())
1119	        else {
1120	            log::error!("Dock menu for index {action_idx} not found");
1121	            return Some(1);
