1410	fn handle_gpu_device_lost(
1411	    directx_devices: &mut DirectXDevices,
1412	    platform_window: HWND,
1413	    validation_number: usize,
1414	    all_windows: &std::sync::Weak<RwLock<SmallVec<[SafeHwnd; 4]>>>,
1415	    text_system: &std::sync::Weak<DirectWriteTextSystem>,
1416	) -> Result<()> {
1417	    // Here we wait a bit to ensure the system has time to recover from the device lost state.
1418	    // If we don't wait, the final drawing result will be blank.
1419	    std::thread::sleep(std::time::Duration::from_millis(350));
1420	
1421	    *directx_devices = try_to_recover_from_device_lost(|| {
1422	        DirectXDevices::new().context("Failed to recreate new DirectX devices after device lost")
1423	    })?;
1424	    log::info!("DirectX devices successfully recreated.");
1425	
1426	    let lparam = LPARAM(directx_devices as *const _ as _);
1427	    unsafe {
1428	        SendMessageW(
1429	            platform_window,
1430	            WM_GPUI_GPU_DEVICE_LOST,
1431	            Some(WPARAM(validation_number)),
1432	            Some(lparam),
1433	        );
1434	    }
1435	
1436	    if let Some(text_system) = text_system.upgrade() {
1437	        text_system.handle_gpu_lost(&directx_devices)?;
1438	    }
1439	    if let Some(all_windows) = all_windows.upgrade() {
1440	        for window in all_windows.read().iter() {
1441	            unsafe {
1442	                SendMessageW(
1443	                    window.as_raw(),
1444	                    WM_GPUI_GPU_DEVICE_LOST,
1445	                    Some(WPARAM(validation_number)),
1446	                    Some(lparam),
1447	                );
1448	            }
1449	        }
1450	        std::thread::sleep(std::time::Duration::from_millis(200));
1451	        for window in all_windows.read().iter() {
1452	            unsafe {
1453	                SendMessageW(
1454	                    window.as_raw(),
1455	                    WM_GPUI_FORCE_UPDATE_WINDOW,
1456	                    Some(WPARAM(validation_number)),
1457	                    None,
1458	                );
1459	            }
1460	        }
1461	    }
1462	    Ok(())
1463	}
