1476	unsafe extern "system" fn window_procedure(
1477	    hwnd: HWND,
1478	    msg: u32,
1479	    wparam: WPARAM,
1480	    lparam: LPARAM,
1481	) -> LRESULT {
1482	    if msg == WM_NCCREATE {
1483	        let params = unsafe { &*(lparam.0 as *const CREATESTRUCTW) };
1484	        let creation_context = params.lpCreateParams as *mut PlatformWindowCreateContext;
1485	        let creation_context = unsafe { &mut *creation_context };
1486	
1487	        let Some(main_sender) = creation_context.main_sender.take() else {
1488	            creation_context.inner = Some(Err(anyhow!("missing main sender")));
1489	            return LRESULT(0);
1490	        };
1491	        creation_context.dispatcher = Some(Arc::new(WindowsDispatcher::new(
1492	            main_sender,
1493	            hwnd,
1494	            creation_context.validation_number,
1495	        )));
1496	
1497	        return match WindowsPlatformInner::new(creation_context) {
1498	            Ok(inner) => {
1499	                let weak = Box::new(Rc::downgrade(&inner));
1500	                unsafe { set_window_long(hwnd, GWLP_USERDATA, Box::into_raw(weak) as isize) };
1501	                creation_context.inner = Some(Ok(inner));
1502	                unsafe { DefWindowProcW(hwnd, msg, wparam, lparam) }
1503	            }
1504	            Err(error) => {
1505	                creation_context.inner = Some(Err(error));
1506	                LRESULT(0)
1507	            }
1508	        };
1509	    }
1510	
1511	    let ptr = unsafe { get_window_long(hwnd, GWLP_USERDATA) } as *mut Weak<WindowsPlatformInner>;
1512	    if ptr.is_null() {
1513	        return unsafe { DefWindowProcW(hwnd, msg, wparam, lparam) };
1514	    }
1515	    let inner = unsafe { &*ptr };
1516	    let result = if let Some(inner) = inner.upgrade() {
1517	        if cfg!(debug_assertions) {
1518	            let inner = std::panic::AssertUnwindSafe(inner);
1519	            match std::panic::catch_unwind(|| { inner }.handle_msg(hwnd, msg, wparam, lparam)) {
1520	                Ok(result) => result,
1521	                Err(_) => std::process::abort(),
1522	            }
1523	        } else {
1524	            inner.handle_msg(hwnd, msg, wparam, lparam)
1525	        }
1526	    } else {
1527	        unsafe { DefWindowProcW(hwnd, msg, wparam, lparam) }
1528	    };
1529	
1530	    if msg == WM_NCDESTROY {
1531	        unsafe { set_window_long(hwnd, GWLP_USERDATA, 0) };
1532	        unsafe { drop(Box::from_raw(ptr)) };
1533	    }
1534	
1535	    result
1536	}
